import{_ as o}from"./chunks/architecture.Cs8uKTTN.js";import{_ as r,o as a,c as t,a2 as c}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"システムアーキテクチャ設計","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/dev-guide/architecture.md","filePath":"ja-JP/dev-guide/architecture.md","lastUpdated":1787586465000}'),i={name:"ja-JP/dev-guide/architecture.md"};function l(d,e,s,n,h,p){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="システムアーキテクチャ設計" tabindex="-1">システムアーキテクチャ設計 <a class="header-anchor" href="#システムアーキテクチャ設計" aria-label="Permalink to &quot;システムアーキテクチャ設計&quot;">​</a></h1><p>Lertaro は、ミリ秒単位の超高速検索と高度なデスクトップ統合を実現しつつ、最高のシステム安定性とセキュリティを確保するために、疎結合なマルチプロセス分離モデルを採用しています。</p><p><img src="'+o+'" alt="Lertaro アーキテクチャ図"></p><h2 id="_1-3-プロセス分離モデル" tabindex="-1">1. 3 プロセス分離モデル <a class="header-anchor" href="#_1-3-プロセス分離モデル" aria-label="Permalink to &quot;1. 3 プロセス分離モデル&quot;">​</a></h2><p>単一コンポーネントの不具合によるシステム全体のクラッシュを防ぎ、管理者権限の範囲を最小限に抑えるため、Lertaro の実行環境は 3 つのプロセスに明確に分離されています。</p><h3 id="_1-バックグラウンドインデックスサービス-lertaro-service" tabindex="-1">1. バックグラウンドインデックスサービス（<code>Lertaro.Service</code>） <a class="header-anchor" href="#_1-バックグラウンドインデックスサービス-lertaro-service" aria-label="Permalink to &quot;1. バックグラウンドインデックスサービス（`Lertaro.Service`）&quot;">​</a></h3><ul><li><strong>実行権限</strong>：Windows システムの <code>LocalSystem</code> 権限で常駐する Windows サービス。</li><li><strong>担当範囲</strong>：全ドライブのインデックス作成と変更監視を担当。NTFS / ReFS ドライブの USN 変更ジャーナルおよび $MFT を直接読み取り、FAT32 / exFAT の変更イベントを監視し、SMB / NAS 共有を定期的にキャッシュします。</li><li><strong>セキュリティと性能</strong>：SYSTEM 権限で実行されるため UAC プロンプトなしで低レベルのボリュームメタデータに直接アクセスでき、高速な名前付きパイプを通じて結果をユーザープロセスの App に返します。UI プロセスに不要な管理者権限を持たせない安全な設計です。</li></ul><h3 id="_2-ユーザー-ui-メインプロセス-lertaro-app" tabindex="-1">2. ユーザー UI メインプロセス（<code>Lertaro.App</code>） <a class="header-anchor" href="#_2-ユーザー-ui-メインプロセス-lertaro-app" aria-label="Permalink to &quot;2. ユーザー UI メインプロセス（`Lertaro.App`）&quot;">​</a></h3><ul><li><strong>実行権限</strong>：標準ユーザー権限で動作するセッション分離された WPF デスクトップアプリ。</li><li><strong>担当範囲</strong>：クイック検索ウィンドウ、メイン検索ウィンドウ、設定画面、グローバルホットキー処理、アクションメニュー（<code>Ctrl+O</code>）、QuickLook プレビューを担当。</li><li><strong>IPC と CLI 共有</strong>：名前付きパイプ（<code>Core.Services.SearchService</code>）を介してサービスと通信します。また、ユーザーごとの名前付きパイプ（<code>AppSearchPipeService</code>）をホストしており、<code>lff</code> コマンドラインツールが App の構築済みメモリテーブルやプラグインを再初期化なしで共有利用できます。</li></ul><h3 id="_3-キーボードフック・ウィンドウ統合プロセス-lertaro-service-hook" tabindex="-1">3. キーボードフック・ウィンドウ統合プロセス（<code>Lertaro.Service --hook</code>） <a class="header-anchor" href="#_3-キーボードフック・ウィンドウ統合プロセス-lertaro-service-hook" aria-label="Permalink to &quot;3. キーボードフック・ウィンドウ統合プロセス（`Lertaro.Service --hook`）&quot;">​</a></h3><ul><li><strong>実行権限</strong>：バックグラウンドサービスから必要に応じて起動される専用の特権プロセス。</li><li><strong>担当範囲</strong>：低レベルキーボードフックおよびマウス監視を担当。</li><li><strong>UIPI の回避と耐障害性</strong>：Windows の UIPI（ユーザーインターフェイス特権の分離）により、低権限プロセスから管理者権限で実行中のウィンドウへメッセージを送信することは制限されています。この特権 Hook プロセス上でウィンドウアダプター（<a href="./sdk/system-adapters.html"><code>IActivePathCollector</code>, <code>IFileDialogAdapter</code>, <code>IInlineSearchAdapter</code></a>）を実行することで、管理者権限のエクスプローラーやダイアログにも支障なくフックできます。また、フック処理がクラッシュしてもメイン App には影響しません。</li></ul><h2 id="_2-共通コアライブラリ-lertaro-core" tabindex="-1">2. 共通コアライブラリ（<code>Lertaro.Core</code>） <a class="header-anchor" href="#_2-共通コアライブラリ-lertaro-core" aria-label="Permalink to &quot;2. 共通コアライブラリ（`Lertaro.Core`）&quot;">​</a></h2><p><code>Lertaro.Core</code> は、Service、App、Hook の各プロセスから共通して参照される基本ライブラリです。</p><ul><li><strong>独自 fzf あいまい一致エンジン（<code>Core/SearchIndex/Fzf/*</code>）</strong>：<code>fzf</code> アルゴリズムに基づく高速な文字飛び一致、スコアリング、ハイライトマスク計算を実装。</li><li><strong>列指向インメモリインデックス（<code>Core/IndexV2/*</code>）</strong>：メモリマップト列指向スナップショットとインメモリ差分レイヤーにより、数億件のファイルからミリ秒未満で結果を抽出。</li><li><strong>バイナリ IPC 通信仕様</strong>：<code>SearchRequestMessage</code> などの標準バイナリプロトコルにより、プロセス間でゼロコピーに近い高速なシリアライズを実現。</li><li><strong>統合ログシステム（<code>Logger</code>）</strong>：<code>service.log</code>、<code>app.log</code>、<code>hook.log</code> にそれぞれ出力し、設定画面のログビューアーから統合的に閲覧可能。</li></ul><h2 id="_3-プラグインシステムのアーキテクチャ上の位置づけ" tabindex="-1">3. プラグインシステムのアーキテクチャ上の位置づけ <a class="header-anchor" href="#_3-プラグインシステムのアーキテクチャ上の位置づけ" aria-label="Permalink to &quot;3. プラグインシステムのアーキテクチャ上の位置づけ&quot;">​</a></h2><p>すべてのプラグインは <code>Lertaro.PluginSdk</code> をベースに構築され、<code>Lertaro.App</code> 起動時に動的ロードされます。</p><ul><li><strong>標準コンポーネント</strong>：通常の検索ソース、アクション、UI 拡張は App プロセス内のみで動作し、Service に直接アクセスすることはありません（ディレクトリのインデックス登録は <code>DirectoryIndexerService</code> を介して依頼）。</li><li><strong>特権アダプターの二重ロード</strong>：ウィンドウ統合用のアダプター（<code>IActivePathCollector</code> 等）は、管理者権限ウィンドウとの連携を担保するため、Hook プロセス側にも追加ロードされて実行されます。</li></ul>',17)])])}const S=r(i,[["render",l]]);export{_ as __pageData,S as default};
